buildscript {
    ext {
        rnsDefaultTargetSdkVersion = 34
        rnsDefaultCompileSdkVersion = 34
        rnsDefaultMinSdkVersion = 21
        rnsDefaultKotlinVersion = '1.8.0'
    }
    ext.safeExtGet = {prop, fallback ->
        def props = (prop instanceof String) ? [prop] : prop
        def result = props.find { key ->
            return rootProject.ext.has(key)
        }
        return result ? rootProject.ext.get(result) : fallback
    }
    repositories {
        google()
        mavenCentral()
    }
    dependencies {
        def isRunningInContextOfScreensRepo = project == rootProject
        if (isRunningInContextOfScreensRepo) {
            classpath('com.android.tools.build:gradle:8.2.1')
            classpath "org.jetbrains.kotlin:kotlin-gradle-plugin:${safeExtGet('kotlinVersion', rnsDefaultKotlinVersion)}"
            classpath "com.diffplug.spotless:spotless-plugin-gradle:6.25.0"
        }
    }
}

def isRunningInContextOfScreensRepo() {
    return project == rootProject
}

def areDebugLogsEnabled() {
    return project.hasProperty("rnsDebugLogsEnabled") && project.rnsDebugLogsEnabled == "true"
}

def isGammaEnabled() {
    return project.hasProperty("rnsGammaEnabled") && project.rnsGammaEnabled == "true"
}

def resolveReactNativeDirectory() {
    def userDefinedRnDirPath = safeAppExtGet("REACT_NATIVE_NODE_MODULES_DIR", null)
    if (userDefinedRnDirPath != null) {
        return file(userDefinedRnDirPath)
    }

    File standardRnDirFile = file("$rootDir/../node_modules/react-native/")
    if (standardRnDirFile.exists()) {
        return standardRnDirFile
    }

    // This is legacy code, I'm not sure why it works in certain scenarios but it was reported that one of our
    // projects needs this.
    File legacyRnDirFile = file("$projectDir/../node_modules/react-native/")
    if (legacyRnDirFile.exists()) {
        return legacyRnDirFile
    }

    // We're in non standard setup, e.g. monorepo - try to use node resolver to locate the react-native package.
    String maybeRnPackagePath = providers.exec {
        workingDir(rootDir)
        commandLine("node", "--print", "require.resolve('react-native/package.json')")
    }.standardOutput.asText.get().trim()

    File nodeResolverRnDirFile = null
    // file() constructor fails in case string is null or blank
    if (maybeRnPackagePath != null && !maybeRnPackagePath.isBlank()) {
        File maybeRnPackageFile = file(maybeRnPackagePath)
        if (maybeRnPackageFile.exists()) {
            nodeResolverRnDirFile = maybeRnPackageFile.parentFile
            return nodeResolverRnDirFile
        }
    }

    throw new Exception("[RNScreens] Failed to resolve react-native directory. " +
            "Attempted locations: ${standardRnDirFile}, ${legacyRnDirFile} and ${nodeResolverRnDirFile}. " +
            "You should set project extension property (in `app/build.gradle`) `REACT_NATIVE_NODE_MODULES_DIR` with path to react-native.")
}

// spotless is only accessible within react-native-screens repo, while the RN Gradle
// plugin is registered by the host app's settings.gradle ÔÇö it's not on the classpath
// in standalone repo context, so applying it here would fail during Gradle configuration.
if (isRunningInContextOfScreensRepo()) {
    apply from: 'spotless.gradle'
} else {
    apply plugin: "com.facebook.react"
}
apply plugin: 'com.android.library'
apply plugin: 'kotlin-android'

def reactNativeArchitectures() {
    def value = project.getProperties().get("reactNativeArchitectures")
    return value ? value.split(",") : ["armeabi-v7a", "x86", "x86_64", "arm64-v8a"]
}

def safeAppExtGet(prop, fallback) {
    def appProject = rootProject.allprojects.find { it.plugins.hasPlugin('com.android.application') }
    appProject?.ext?.has(prop) ? appProject.ext.get(prop) : fallback
}

def reactNativeRootDir = resolveReactNativeDirectory()

def reactProperties = new Properties()
file("$reactNativeRootDir/ReactAndroid/gradle.properties").withInputStream { reactProperties.load(it) }

def REACT_NATIVE_VERSION = reactProperties.getProperty("VERSION_NAME")
def REACT_NATIVE_MINOR_VERSION = REACT_NATIVE_VERSION.startsWith("0.0.0-") ? 1000 : REACT_NATIVE_VERSION.split("\\.")[1].toInteger()

android {
    compileSdkVersion safeExtGet('compileSdkVersion', rnsDefaultCompileSdkVersion)
    namespace "com.swmansion.rnscreens"

    // Used to override the NDK path/version on internal CI or by allowing
    // users to customize the NDK path/version from their root project (e.g. for M1 support)
    if (rootProject.hasProperty("ndkPath")) {
        ndkPath rootProject.ext.ndkPath
    }
    if (rootProject.hasProperty("ndkVersion")) {
        ndkVersion rootProject.ext.ndkVersion
    }

    defaultConfig {
        minSdkVersion safeExtGet(['minSdkVersion', 'minSdk'], rnsDefaultMinSdkVersion)
        targetSdkVersion safeExtGet(['targetSdkVersion', 'targetSdk'], rnsDefaultTargetSdkVersion)
        versionCode 1
        versionName "1.0"
        buildConfigField "boolean", "RNS_GAMMA_ENABLED", isGammaEnabled().toString()
        buildConfigField "boolean", "RNS_DEBUG_LOGGING", areDebugLogsEnabled().toString()
        ndk {
            abiFilters (*reactNativeArchitectures())
        }
        externalNativeBuild {
            cmake {
                arguments "-DANDROID_STL=c++_shared",
                        "-DANDROID_SUPPORT_FLEXIBLE_PAGE_SIZES=ON"
            }
        }
    }
    buildFeatures {
        prefab true
        buildConfig true
    }
    externalNativeBuild {
        cmake {
            path "CMakeLists.txt"
        }
    }
    lintOptions {
        abortOnError false
    }
    compileOptions {
        sourceCompatibility JavaVersion.VERSION_1_8
        targetCompatibility JavaVersion.VERSION_1_8
    }
    packagingOptions {
        // Several RN-provided .so are copied into this library's build intermediates and can collide when
        // the app merges native libs. We can only specify exclude (not include) patterns, so we exclude
        // these (ideally we'd keep only librnscreens.so).
        excludes = [
                "META-INF",
                "META-INF/**",
                "**/libjsi.so",
                "**/libc++_shared.so",
                "**/libfbjni.so",
                // RN's renderer / jni / performance-timeline libs (libreact_render*.so, libreactnativejni.so,
                // libreact_performance_timeline.so) are merged into libreactnative.so since RN 0.76
                // (facebook/react-native#46059), so on supported RN (>= 0.82) only libreactnative.so needs excluding.
                "**/libreactnative.so"
        ]
    }
    sourceSets.main {
        ext.androidResDir = "src/main/res"
        java {
            srcDirs += [
                "src/fabric/java",
            ]
        }
        res {
            if (safeExtGet(['compileSdkVersion', 'compileSdk'], rnsDefaultCompileSdkVersion) >= 33) {
                srcDirs = ["${androidResDir}/base", "${androidResDir}/v33"]
            } else {
                srcDirs = ["${androidResDir}/base"]
            }
        }
    }
}

repositories {
    maven {
        url "${reactNativeRootDir}/android"
    }

    mavenCentral()
    mavenLocal()
    google()
}

dependencies {
    implementation 'com.facebook.react:react-native:+'
    implementation 'androidx.appcompat:appcompat:1.7.1'
    implementation 'androidx.fragment:fragment-ktx:1.8.9'
    implementation 'androidx.transition:transition-ktx:1.7.0'
    implementation 'androidx.coordinatorlayout:coordinatorlayout:1.2.0'
    implementation 'androidx.swiperefreshlayout:swiperefreshlayout:1.1.0'
    implementation 'com.google.android.material:material:1.13.0'
    implementation "androidx.core:core-ktx:1.17.0"
}

import groovy.json.JsonSlurper
import org.apache.tools.ant.taskdefs.condition.Os
import org.jetbrains.kotlin.gradle.dsl.JvmTarget
import java.util.Properties
import javax.inject.Inject

plugins {
    id("com.android.library")
    id("maven-publish")
    id("com.diffplug.spotless") version "8.1.0"
    id("org.jetbrains.kotlin.android")
}

fun safeExtGet(prop: String, fallback: Any?): Any? =
    if (rootProject.extensions.extraProperties.has(prop)) rootProject.extensions.extraProperties.get(prop) else fallback

fun safeAppExtGet(prop: String, fallback: Any?): Any? {
    val appProject = rootProject.allprojects.find { it.plugins.hasPlugin("com.android.application") }
    return if (appProject?.extensions?.extraProperties?.has(prop) == true)
        appProject.extensions.extraProperties.get(prop)
    else
        fallback
}

fun resolveReactNativeDirectory(): File {
    val reactNativeLocation = safeAppExtGet("REACT_NATIVE_NODE_MODULES_DIR", null) as String?
    if (reactNativeLocation != null) {
        return file(reactNativeLocation)
    }

    // Fallback to node resolver for custom directory structures like monorepos.
    val reactNativePackage = file(
        providers.exec {
            workingDir(rootDir)
            commandLine("node", "--print", "require.resolve('react-native/package.json')")
        }.standardOutput.asText.get().trim()
    )
    if (reactNativePackage.exists()) {
        return reactNativePackage.parentFile
    }

    throw GradleException(
        "[Worklets] Unable to resolve react-native location in node_modules. You should set project extension property (in `app/build.gradle`) named `REACT_NATIVE_NODE_MODULES_DIR` with the path to react-native in node_modules."
    )
}

fun getReactNativeVersion(): String {
    val reactNativeRootDir = resolveReactNativeDirectory()
    val reactProperties = Properties()
    file("$reactNativeRootDir/ReactAndroid/gradle.properties").inputStream().use { reactProperties.load(it) }
    return reactProperties.getProperty("VERSION_NAME")
}

fun getReactNativeMinorVersion(): Int {
    val reactNativeVersion = getReactNativeVersion()
    return if (reactNativeVersion.startsWith("0.0.0-")) 1000 else reactNativeVersion.split(".")[1].toInt()
}

fun getHermesV1Enabled(): Boolean {
    // Even though `HERMES_V1_ENABLED` is now centralized
    // in `react-native-flags.cmake` for React Native >= 0.84
    // that CMake file depends on definitions provided
    // in local `externalNativeBuild` configuration of the LIBRARY.
    // I hope this is only a temporary workaround.
    return if (getReactNativeMinorVersion() >= 84) {
        safeAppExtGet("hermesV1Enabled", true)?.toString()?.toBoolean() ?: true
    } else {
        safeAppExtGet("hermesV1Enabled", false)?.toString()?.toBoolean() ?: false
    }
}

fun getWorkletsVersion(): String {
    val inputFile = file("${projectDir.path}/../package.json")
    val json = JsonSlurper().parseText(inputFile.readText()) as Map<*, *>
    return json["version"]?.toString() ?: throw GradleException("[Worklets] Cannot find version in package.json")
}

fun toPlatformFileString(path: String): String {
    var result = path
    if (Os.isFamily(Os.FAMILY_WINDOWS)) {
        result = result.replace(File.separatorChar, '/')
    }
    return result
}

fun getStaticFeatureFlags(): Map<String, String> {
    val featureFlags = HashMap<String, String>()

    val staticFeatureFlagsFile = file("${projectDir.path}/../src/featureFlags/staticFlags.json")
    if (!staticFeatureFlagsFile.exists()) {
        throw GradleException("[Worklets] Feature flags file not found at ${staticFeatureFlagsFile.absolutePath}.")
    }
    (JsonSlurper().parseText(staticFeatureFlagsFile.readText()) as Map<*, *>).forEach { (key, value) ->
        featureFlags[key.toString()] = value.toString()
    }

    val packageJsonFile = file("${rootDir.path}/../package.json")
    if (packageJsonFile.exists()) {
        val packageJson = JsonSlurper().parseText(packageJsonFile.readText()) as Map<*, *>
        (packageJson["worklets"] as? Map<*, *>)
            ?.get("staticFeatureFlags")
            ?.let { it as? Map<*, *> }
            ?.forEach { (key, value) -> featureFlags[key.toString()] = value.toString() }
    }

    return featureFlags
}

fun getStaticFeatureFlagsString(featureFlags: Map<String, String>): String =
    featureFlags.entries.joinToString("") { (key, value) -> "[$key:$value]" }

fun isFlagEnabled(featureFlags: Map<String, String>, flagName: String): Boolean =
    featureFlags.containsKey(flagName) && featureFlags[flagName] == "true"

